(function(root){'use strict';
const sideOf=c=>c.row>5?'you':'partner',gemKey=g=>g.id+':'+g.grade;
function active(state){return{cells:state.cells.filter(c=>state.partnerEnabled||sideOf(c)==='you'),marks:(state.marks||[]).filter(c=>state.partnerEnabled||sideOf(c)==='you')}}
function penalty(defence){const deficit=Math.max(0,75-Math.max(0,defence));return{defence,deficit,factor:Math.max(0,1-deficit/100)}}
function inventoryOf(state,side){state.inventory??={you:[],partner:[]};return state.inventory[side]??=[]}
function usage(cells,p,side){const used=new Map;const slugs=new Set(cells.filter(c=>sideOf(c)===side).map(c=>c.slug));for(const slug of slugs){const copies=cells.filter(c=>sideOf(c)===side&&c.slug===slug).length;for(const gem of p.perDemon[slug]?.gems||[])if(gem.id)used.set(gemKey(gem),(used.get(gemKey(gem))||0)+copies)}return used}
function collectEquipped(state,side,force=false){const list=inventoryOf(state,side),p=state[side],used=usage(state.cells,p,side);for(const [slug,settings]of Object.entries(p.perDemon)){if(state.cells.some(c=>sideOf(c)===side&&c.slug===slug))continue;for(const gem of settings.gems||[])if(gem.id)used.set(gemKey(gem),Math.max(used.get(gemKey(gem))||0,1))}for(const [key,count]of used){let gem=list.find(g=>gemKey(g)===key);if(gem){if(force||gem.manual===false)gem.count=Math.max(gem.count,count)}else{const split=key.lastIndexOf(':');list.push({id:key.slice(0,split),grade:key.slice(split+1),count,manual:false})}}return list}
function validLoadout(groups,build,inventory,gemById){const stock=new Map(inventory.map(g=>[gemKey(g),g.count])),used=new Map;for(const group of groups){const gems=build[group.slug]?.gems||[],ids=new Set;for(let slot=0;slot<3;slot++){const gem=gems[slot];if(!gem?.id)continue;const data=gemById.get(gem.id);if(!data||group.lib<[3,10,20][slot]||!!data.special!==(slot===1)||ids.has(gem.id))return false;ids.add(gem.id);const key=gemKey(gem),count=(used.get(key)||0)+group.copies;if(count>(stock.get(key)||0))return false;used.set(key,count)}}return true}
// Recommendation-only rule: Awakening's 40-wave silence is reserved for Ivy.
const recommendable=(slug,gem)=>gem.id!=='awakening'||slug==='ivy';
const recommendationPolicyValid=(groups,build)=>groups.every(g=>(build[g.slug]?.gems||[]).every(gem=>recommendable(g.slug,gem)));
async function recommend({groups,build,inventory,gemById,evaluate,maxEvaluations=300,timeLimit=20000,onProgress=()=>{},cancelled=()=>false}){
const clone=x=>structuredClone(x),blank=()=>({id:'',grade:'S'}),started=performance.now();let evaluated=0;
const original=clone(build),current=clone(build),stock=inventory.filter(g=>g.count>0&&gemById.has(g.id));
for(const g of groups)current[g.slug]={...current[g.slug],gems:[blank(),blank(),blank()]};
// Retain only legal equipment that fits the actual shared stock (copies included).
for(const g of groups)for(let slot=0;slot<3;slot++){const gem=original[g.slug]?.gems?.[slot];if(!gem?.id||!recommendable(g.slug,gem))continue;current[g.slug].gems[slot]=clone(gem);if(!validLoadout(groups,current,stock,gemById))current[g.slug].gems[slot]=blank()}
const run=async b=>{evaluated++;return evaluate(b)},baseline=await run(original);let bestBuild=clone(current),best=await run(bestBuild),now=clone(bestBuild);const inBudget=()=>evaluated<maxEvaluations&&performance.now()-started<timeLimit&&!cancelled();
const tryBuild=async candidate=>{if(!recommendationPolicyValid(groups,candidate)||!validLoadout(groups,candidate,stock,gemById))return false;let result;try{result=await run(candidate)}catch{return false}const improves=result.actual>best.actual+Math.max(1,best.actual)*1e-10;if(improves){best=result;bestBuild=clone(candidate);now=clone(candidate)}onProgress({evaluated,best:best.actual,baseline:baseline.actual});await new Promise(resolve=>setTimeout(resolve,0));return improves};
let passes=0;while(inBudget()){let improved=false;for(const group of groups){for(let slot=0;slot<3;slot++){if(group.lib<[3,10,20][slot])continue;const choices=[blank(),...stock.filter(g=>recommendable(group.slug,g)&&!!gemById.get(g.id).special===(slot===1))];for(const gem of choices){if(!inBudget())break;if(gemKey(now[group.slug].gems[slot])===gemKey(gem))continue;const candidate=clone(now);candidate[group.slug].gems[slot]={id:gem.id,grade:gem.grade};if(await tryBuild(candidate))improved=true}}if(!inBudget())break}
if(!improved&&inBudget()){const slots=groups.flatMap(g=>[0,1,2].filter(s=>g.lib>=[3,10,20][s]).map(slot=>({slug:g.slug,slot})));for(let i=0;i<slots.length&&inBudget();i++)for(let j=i+1;j<slots.length&&inBudget();j++){const a=slots[i],b=slots[j];if((a.slot===1)!==(b.slot===1))continue;const candidate=clone(now),ga=candidate[a.slug].gems[a.slot],gb=candidate[b.slug].gems[b.slot];candidate[a.slug].gems[a.slot]=gb;candidate[b.slug].gems[b.slot]=ga;if(await tryBuild(candidate))improved=true}}
passes++;if(!improved)break}
return{build:bestBuild,result:best,baseline:baseline.actual,evaluated,passes,cancelled:cancelled(),originalValid:validLoadout(groups,original,stock,gemById),originalPolicyValid:recommendationPolicyValid(groups,original),awakeningPolicy:'ivy-only'};
}
root.CoopGemTools={sideOf,gemKey,active,penalty,inventoryOf,usage,collectEquipped,validLoadout,recommend};if(typeof module!=='undefined')module.exports=root.CoopGemTools;
})(globalThis);
